package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RetentionDaysVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property retention days of observed source ")
  void test_retention_days_v_o_builder() {
    Assertions.assertFalse(RetentionDaysVO.nullValue().getRetentionDays().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(RetentionDaysVO.tryFrom(null).getRetentionDays().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, RetentionDaysVO.from(1).getRetentionDays().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RetentionDaysVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", RetentionDaysVO.from(1).toString());
  }
}
